/* Button.module.css */
.primary {
  background: blue;
  color: white;
  padding: 10px 20px;
}

.secondary {
  background: gray;
  color: white;
  padding: 10px 20px;
}

import styles from './Button.module.css';

function Button({ variant = 'primary', children }) {
  return (
    <button className={styles[variant]}>
      {children}
    </button>
  );
}

// Usage
<Button variant="primary">Click me</Button>

/* styles.module.css */
.base {
  padding: 10px 20px;
  border: none;
  border-radius: 4px;
}

.primary {
  composes: base;
  background: blue;
  color: white;
}

.large {
  composes: base;
  font-size: 1.5rem;
}
